export function Agent({
  name = "{{name}}",
  goal = "{{goal}}",
  status = "{{status}}",
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  const badge = {
    active: { background: accent, color: "#241430", borderColor: accent },
    paused: { background: "transparent", color: accent, borderColor: accent },
    done: { background: "transparent", color: "#24143066", borderColor: "#24143033" },
  }[status] ?? {};
  return (
    <div style={{ maxWidth: 360, padding: "16px 18px", background: "#FAF7F2", color: "#241430",
      border: "1.5px solid #24143022", borderRadius: radius, boxSizing: "border-box", fontFamily: "system-ui, sans-serif" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <span aria-hidden="true" style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 38,
          height: 38, borderRadius: "50%", background: accent, fontSize: 18, flexShrink: 0 }}>&#129302;</span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <p style={{ margin: "0 0 4px", fontWeight: 700, fontSize: 15 }}>{name}</p>
          <span style={{ display: "inline-block", textTransform: "capitalize", fontSize: 11, fontWeight: 700,
            padding: "0.25em 0.7em", borderRadius: 999, border: "1.5px solid", ...badge }}>{status}</span>
        </div>
      </div>
      <p style={{ margin: "12px 0 0", fontSize: 13, color: "#241430cc" }}>
        <span style={{ fontWeight: 600, color: "#241430" }}>Goal:</span> {goal}
      </p>
    </div>
  );
}
